<?php
namespace Tests\Feature;
use App\Models\Company; use App\Models\ShortUrl; use App\Models\User; use Illuminate\Foundation\Testing\RefreshDatabase; use Illuminate\Support\Facades\Hash; use Tests\TestCase;
class UrlAuthorizationTest extends TestCase { use RefreshDatabase;
 private function user(string $role, ?int $companyId): User { return User::create(['name'=>$role,'email'=>strtolower($role).uniqid().'@example.com','password'=>Hash::make('password'),'role'=>$role,'company_id'=>$companyId]); }
 protected function setUp(): void { parent::setUp(); Company::create(['name'=>'A']); Company::create(['name'=>'B']); }
 public function test_admin_member_and_superadmin_cannot_create_short_urls(): void { $company=Company::first(); foreach(['Admin','Member','SuperAdmin'] as $role){ $user=$this->user($role,$role==='SuperAdmin'?null:$company->id); $this->actingAs($user)->get('/urls/create')->assertForbidden(); $this->actingAs($user)->post('/urls',['original_url'=>'https://example.com'])->assertForbidden(); } }
 public function test_admin_only_sees_urls_outside_their_company(): void { $a=Company::where('name','A')->first(); $b=Company::where('name','B')->first(); $admin=$this->user('Admin',$a->id); $ownerA=$this->user('Sales',$a->id); $ownerB=$this->user('Sales',$b->id); ShortUrl::create(['company_id'=>$a->id,'created_by'=>$ownerA->id,'code'=>'aaaa1111','original_url'=>'https://a.example']); ShortUrl::create(['company_id'=>$b->id,'created_by'=>$ownerB->id,'code'=>'bbbb2222','original_url'=>'https://b.example']); $this->actingAs($admin)->get('/urls')->assertOk()->assertDontSee('https://a.example')->assertSee('https://b.example'); }
 public function test_member_only_sees_urls_not_created_by_themselves(): void { $c=Company::first(); $member=$this->user('Member',$c->id); $other=$this->user('Sales',$c->id); ShortUrl::create(['company_id'=>$c->id,'created_by'=>$member->id,'code'=>'aaaa1111','original_url'=>'https://mine.example']); ShortUrl::create(['company_id'=>$c->id,'created_by'=>$other->id,'code'=>'bbbb2222','original_url'=>'https://other.example']); $this->actingAs($member)->get('/urls')->assertOk()->assertDontSee('https://mine.example')->assertSee('https://other.example'); }
 public function test_short_urls_require_login_and_authorization_to_redirect(): void { $c=Company::first(); $creator=$this->user('Sales',$c->id); $url=ShortUrl::create(['company_id'=>$c->id,'created_by'=>$creator->id,'code'=>'aaaa1111','original_url'=>'https://destination.example']); $this->get('/s/aaaa1111')->assertRedirect('/login'); $this->actingAs($creator)->get('/s/aaaa1111')->assertForbidden(); $member=$this->user('Member',$c->id); $this->actingAs($member)->get('/s/aaaa1111')->assertRedirect('https://destination.example'); }
}
